module optimal_cache (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] c,\n    input wire [4:0] a,\n    input wire [4:0] obj_addr,\n    input wire [3:0] obj_data,\n    input wire obj_write,\n    output reg [7:0] miss_count,\n    output reg done\n);\n    // State encoding\n    localparam [3:0] IDLE  = 4'd0;\n    localparam [3:0] INIT  = 4'd1;\n    localparam [3:0] CHECK = 4'd2;\n    localparam [3:0] MISS  = 4'd3;\n    localparam [3:0] ADD   = 4'd4;\n    localparam [3:0] EVICT = 4'd5;\n    localparam [3:0] NEXT  = 4'd6;\n    localparam [3:0] DONE  = 4'd7;\n\n    // Internal storage\n    reg [3:0] seq [0:15];\n    reg [3:0] cache [0:3];\n    reg valid [0:3];\n    reg [3:0] state, next_state;\n    reg [4:0] current_index;\n    reg [2:0] occupied;\n\n    // Combinational signals\n    wire hit;\n    wire [2:0] hit_slot;\n    wire has_empty;\n    wire [2:0] empty_slot;\n    wire [4:0] next_use [0:3];\n    wire [2:0] evict_slot;\n\n    integer i, j;\n\n    // Write sequence memory\n    always @(posedge clk) begin\n        if (obj_write) seq[obj_addr] <= obj_data;\n    end\n\n    // Hit detection\n    always @(*) begin\n        hit = 1'b0;\n        hit_slot = 3'd0;\n        for (i = 0; i < 4; i = i + 1) begin\n            if (i < c && valid[i] && cache[i] == seq[current_index]) begin\n                hit = 1'b1;\n                hit_slot = i;\n            end\n        end\n    end\n\n    // Empty slot detection\n    always @(*) begin\n        has_empty = 1'b0;\n        empty_slot = 3'd0;\n        for (i = 0; i < 4; i = i + 1) begin\n            if (i < c && !valid[i]) begin\n                has_empty = 1'b1;\n                empty_slot = i;\n            end\n        end\n    end\n\n    // Next use computation\n    always @(*) begin\n        for (i = 0; i < 4; i = i + 1) begin\n            next_use[i] = a;\n            if (i < c && valid[i]) begin\n                for (j = current_index + 1; j < 16; j = j + 1) begin\n                    if (j < a && seq[j] == cache[i] && next_use[i] == a) begin\n                        next_use[i] = j;\n                    end\n                end\n            end\n        end\n    end\n\n    // Eviction logic\n    always @(*) begin\n        evict_slot = 3'd0;\n        for (i = 1; i < 4; i = i + 1) begin\n            if (i < c && next_use[i] > next_use[evict_slot]) begin\n                evict_slot = i;\n            end\n        end\n    end\n\n    // State register\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            miss_count <= 8'd0;\n            current_index <= 5'd0;\n            occupied <= 3'd0;\n            for (i = 0; i < 4; i = i + 1) begin\n                valid[i] <= 1'b0;\n                cache[i] <= 4'd0;\n            end\n            for (i = 0; i < 16; i = i + 1) begin\n                seq[i] <= 4'd0;\n            end\n        end else begin\n            state <= next_state;\n            case (state)\n                INIT: begin\n                    current_index <= 5'd0;\n                    occupied <= 3'd0;\n                    miss_count <= 8'd0;\n                    done <= 1'b0;\n                    for (i = 0; i < 4; i = i + 1) begin\n                        valid[i] <= 1'b0;\n                    end\n                end\n                ADD: begin\n                    cache[empty_slot] <= seq[current_index];\n                    valid[empty_slot] <= 1'b1;\n                    occupied <= occupied + 3'd1;\n                end\n                EVICT: begin\n                    cache[evict_slot] <= seq[current_index];\n                end\n                NEXT: begin\n                    current_index <= current_index + 5'd1;\n                end\n                DONE: done <= 1'b1;\n            endcase\n        end\n    end\n\n    // Next state logic\n    always @(*) begin\n        next_state = state;\n        case (state)\n            IDLE: next_state = start ? INIT : IDLE;\n            INIT: next_state = CHECK;\n            CHECK: next_state = hit ? NEXT : MISS;\n            MISS: next_state = (occupied < c) ? ADD : EVICT;\n            ADD: next_state = NEXT;\n            EVICT: next_state = NEXT;\n            NEXT: next_state = (current_index < a - 1) ? CHECK : DONE;\n            DONE: next_state = DONE;\n            default: next_state = IDLE;\n        endcase\n    end\n\n    // Miss counter\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            miss_count <= 8'd0;\n        end else if (state == ADD || state == EVICT) begin\n            miss_count <= miss_count + 8'd1;\n        end\n    end\nendmodule